1: /**
2:  * Small helpers for reading loosely typed JSON payloads.
3:  *
4:  * Registration state is exchanged with the platform as JSON (preferences blob,
5:  * navigation state, service responses) so every boundary converts through the
6:  * functions below instead of scattering casts around the flow.
7:  */
8: 
9: /** Parses a JSON document into a property bag. */
10: export function jsonRecord(source: string): Record<string, Object> {
11:   if (source.length === 0) {
12:     return {} as Record<string, Object>;
13:   }
14:   return JSON.parse(source) as Record<string, Object>;
15: }
16: 
17: /** Deep copies a property bag by round tripping it through JSON. */
18: export function jsonClone(value: Record<string, Object>): Record<string, Object> {
19:   return jsonRecord(JSON.stringify(value));
20: }
21: 
22: /** Reads a member of a property bag as text, tolerating missing or non text members. */
23: export function asText(value: Object | undefined): string {
24:   if (value === undefined || value === null) {
25:     return '';
26:   }
27:   if (typeof value === 'string') {
28:     return value as string;
29:   }
30:   return JSON.stringify(value);
31: }
32: 
33: /** Reads a member of a property bag as a boolean, accepting the usual textual spellings. */
34: export function asFlag(value: Object | undefined): boolean {
35:   if (value === undefined || value === null) {
36:     return false;
37:   }
38:   if (typeof value === 'boolean') {
39:     return value as boolean;
40:   }
41:   const text: string = asText(value);
42:   return text === 'true' || text === '1';
43: }
44: 
45: /** Reads a nested property bag, returning an empty bag when the member is absent. */
46: export function asRecord(value: Object | undefined): Record<string, Object> {
47:   if (value === undefined || value === null) {
48:     return {} as Record<string, Object>;
49:   }
50:   return jsonRecord(JSON.stringify(value));
51: }
52: 
53: /** Reads a member of a property bag that may legitimately be absent. */
54: export function asOptionalText(value: Object | undefined): string | null {
55:   if (value === undefined || value === null) {
56:     return null;
57:   }
58:   const text: string = asText(value);
59:   return text.length === 0 ? null : text;
60: }
61: 
62: /** True when a property bag carries no members at all. */
63: export function isEmptyRecord(value: Record<string, Object>): boolean {
64:   return JSON.stringify(value).length <= 2;
65: }
66: 
67: /** Reads a member, falling back to a default when the member is absent or blank. */
68: export function asTextOr(value: Object | undefined, fallback: string): string {
69:   if (value === undefined || value === null) {
70:     return fallback;
71:   }
72:   const text: string = asText(value);
73:   return text.length === 0 ? fallback : text;
74: }
75: 
76: /** Reads a boolean member, falling back to a default when the member is absent. */
77: export function asFlagOr(value: Object | undefined, fallback: boolean): boolean {
78:   if (value === undefined || value === null) {
79:     return fallback;
80:   }
81:   return asFlag(value);
82: }

