1: /**
2:  * In-app billing boundary for the one-time anti-spam purchase that backs
3:  * phone-numberless Signal registration.
4:  *
5:  * The registration flow never talks to a store plug-in directly. It reads a
6:  * {@link BillingSnapshot} that the billing client cached, and it hands a
7:  * {@link OneTimePurchaseRequest} to the UI layer, because only the UI layer owns
8:  * an Activity able to present the store purchase sheet.
9:  */
10: import { asFlag, asRecord, asText } from './Json';
11: 
12: /** Store level availability of the billing client, as reported by the client itself. */
13: export enum PaymentAvailability {
14:   Unavailable = 'PaymentAvailability.Unavailable',
15:   ServiceUpdating = 'PaymentAvailability.ServiceUpdating',
16:   Available = 'PaymentAvailability.Available'
17: }
