84: /**
85:  * Everything the registration flow is allowed to know about the billing client
86:  * at a point in time. The snapshot is owned outside the flow so that a process
87:  * recreation can rebuild the flow from it.
88:  */
89: export class BillingSnapshot {
90:   googlePlayServices: string = PaymentAvailability.Unavailable;
91:   billingAvailable: boolean = true;
92:   product: BillingProductOption | null = null;
93:   ownedPurchase: BillingPurchase | null = null;
94: 
95:   /** Returns the snapshot to its initial state. */
96:   reset(): void {
97:     this.googlePlayServices = PaymentAvailability.Unavailable;
98:     this.billingAvailable = true;
99:     this.product = null;
100:     this.ownedPurchase = null;
101:   }
102: 
103:   /** Derives the effective availability from the store client state. */
104:   availability(): PaymentAvailability {
105:     if (!this.billingAvailable) {
106:       return PaymentAvailability.Unavailable;
107:     }
108:     const reported: string = this.googlePlayServices;
109:     if (reported === PaymentAvailability.Available) {
110:       return PaymentAvailability.Available;
111:     }
112:     if (reported === PaymentAvailability.ServiceUpdating) {
113:       return PaymentAvailability.ServiceUpdating;
114:     }
115:     return PaymentAvailability.Unavailable;
116:   }
117: 
118:   /** True when the user may reach an owned purchase without paying again. */
119:   hasOwnedUnredeemedPurchase(): boolean {
