125:   restore(given: Record<string, Object>): void {
126:     const services: string = asText(given['googlePlayServices']);
127:     if (services.length > 0) {
128:       this.googlePlayServices = services;
129:     }
130:     if (given['googlePlayBillingAvailable'] !== undefined) {
131:       this.billingAvailable = asFlag(given['googlePlayBillingAvailable']);
132:     }
133:     const product: Record<string, Object> = asRecord(given['billingProduct']);
134:     if (Object.keys(product).length > 0) {
135:       this.product = BillingProductOption.fromJson(product);
136:     }
137:     const owned: Record<string, Object> = asRecord(given['ownedPurchase']);
138:     if (Object.keys(owned).length > 0) {
139:       this.ownedPurchase = BillingPurchase.fromJson(owned);
140:     }
141:   }
142: }
