146:   productId: string = '';
147:   purchaseOptionId: string = '';
148:   formattedPrice: string = '';
149: 
150:   constructor(productId: string, purchaseOptionId: string, formattedPrice: string) {
151:     this.productId = productId;
152:     this.purchaseOptionId = purchaseOptionId;
153:     this.formattedPrice = formattedPrice;
154:   }
155: }
