157: /**
158:  * Contract of the layer that owns the Activity able to present the store
159:  * purchase sheet. The flow stores a reference to it, but never implements it.
160:  */
161: export interface OneTimePurchaseSheet {
162:   present(request: OneTimePurchaseRequest): void;
163: }
