165: /**
166:  * Payment availability that leaves the user without any way to reach the store.
167:  * `ServiceUpdating` is deliberately not terminal: the operating system is in
168:  * the middle of a remediation the user can finish, so the option stays live.
169:  */
170: export function isTerminalAvailability(availability: PaymentAvailability): boolean {
171:   return availability === PaymentAvailability.Unavailable;
172: }

