1: /**
2:  * Signal service boundary used by phone-numberless registration.
3:  *
4:  * Two things matter for this flow:
5:  *  - the anti-spam product identifier is owned by the service, never by the
6:  *    caller, so the client can never substitute its own product;
7:  *  - account creation is driven by a privacy preserving proof of payment. The
8:  *    store purchase token is exchanged for a receipt credential first, and only
9:  *    the receipt credential is ever attached to a registration request.
10:  */
11: import { asFlag, asRecord, asText, asTextOr } from './Json';
