145:     if (Object.keys(response).length > 0) {
146:       this.registrationResponse = RegistrationResponse.fromJson(response);
147:     }
148:     if (given['consumePurchaseSucceeds'] !== undefined) {
149:       this.consumePurchaseSucceeds = asFlag(given['consumePurchaseSucceeds']);
150:     }
151:     const reservation: string = asText(given['serviceAssignedReservation']);
152:     if (reservation.length > 0) {
153:       this.serviceAssignedReservation = reservation;
154:     }
155:     const validationError: string = asTextOr(given['serviceUsernameValidationError'], asTextOr(given['nextUsernameValidationError'], ''));
156:     if (validationError.length > 0) {
