1: /**
2:  * Credential preservation boundary.
3:  *
4:  * A one-time payment buys an account whose only way back in is the issued
5:  * account identifier and recovery key. The client offers to hand those to the
6:  * platform password manager, but never trusts that offer on the strength of the
7:  * save alone: it reads the credential back, filtered by the same account, and
8:  * only an exact two part match counts as safely stored.
9:  */
10: import { asText } from './Json';
11: 
12: /** A username and password credential as stored by the platform password manager. */
13: export class UsernamePasswordCredential {
14:   type: string = 'UsernamePasswordCredential';
15:   username: string = '';
16:   password: string = '';
17: 
18:   constructor(username: string, password: string) {
19:     this.username = username;
20:     this.password = password;
21:   }
22: 
23:   /** Builds a credential from a password manager read-back payload. */
24:   static fromJson(value: Record<string, Object>): UsernamePasswordCredential {
25:     return new UsernamePasswordCredential(asText(value['username']), asText(value['password']));
26:   }
27: 
28:   toJson(): Record<string, Object> {
29:     return { 'type': this.type, 'username': this.username, 'password': this.password } as Record<string, Object>;
30:   }
31: }
32: 
33: /** Where the password manager keeps its single Signal entry. */
34: export interface CredentialStorage {
35:   read(): UsernamePasswordCredential | null;
36: 
37:   write(credential: UsernamePasswordCredential | null): void;
38: 
39:   isAvailable(): boolean;
40: }
41: 
42: /** Normalizes an account identifier for comparison. */
43: export function normalizeAccountId(value: string): string {
44:   return value.trim().toUpperCase();
45: }
46: 
47: /**
48:  * Normalizes a recovery key for comparison. The key is shown to the user in a
49:  * grouped, space separated display form, so a read-back has to be parsed back
50:  * into its compact form before it can be compared with the issued pool.
51:  */
52: export function normalizeRecoveryKey(value: string): string {
53:   return value.replace(/[\s-]/g, '').toUpperCase();
54: }
55: 
56: /**
57:  * Compares a locally entered or read-back credential with the account material
58:  * the registration flow already holds.
59:  *
60:  * Both halves are compared, because either one may have been copied wrongly. A
61:  * partial match is never a confirmation.
62:  */
63: export function credentialMatches(accountId: string, recoveryKey: string, enteredAccountId: string, enteredRecoveryKey: string): boolean {
64:   const accountMatches: boolean = normalizeAccountId(enteredAccountId) === normalizeAccountId(accountId);
65:   const keyMatches: boolean = normalizeRecoveryKey(enteredRecoveryKey) === normalizeRecoveryKey(recoveryKey);
66:   return accountMatches && keyMatches && accountId.length > 0 && recoveryKey.length > 0;
67: }
