69: /** Wraps the platform password manager. */
70: export class SignalCredentialManager {
71:   private storage: CredentialStorage;
72: 
73:   constructor(storage: CredentialStorage) {
74:     this.storage = storage;
75:   }
76: 
77:   isAvailable(): boolean {
78:     return this.storage.isAvailable();
79:   }
80: 
81:   /**
82:    * Records a credential the password manager already holds, for instance one
83:    * written by an earlier session of this app.
84:    */
85:   seed(credential: UsernamePasswordCredential | null): void {
86:     this.storage.write(credential);
87:   }
88: 
89:   /**
90:    * Offers the issued login to the password manager. The account identifier is
91:    * saved in the upper case form the user is shown, the recovery key in its
92:    * display form, and the saved credential is returned to the caller so the
93:    * result can be routed back to the screen that asked for it.
94:    */
95:   saveCredential(accountId: string, recoveryKey: string): UsernamePasswordCredential {
96:     const credential = new UsernamePasswordCredential(normalizeAccountId(accountId), recoveryKey);
97:     this.storage.write(credential);
98:     return credential;
99:   }
100: 
101:   /**
102:    * Reads the credential back. The read-back is filtered by the account the
103:    * flow is currently preserving, so a credential left behind by a different
104:    * account can never be mistaken for a confirmation.
105:    */
106:   getCredential(accountId: string): UsernamePasswordCredential | null {
107:     const stored: UsernamePasswordCredential | null = this.storage.read();
108:     if (stored === null) {
109:       return null;
110:     }
111:     if (normalizeAccountId(stored.username) !== normalizeAccountId(accountId)) {
