242: /** Owns the state and the decisions of phone-numberless registration. */
243: export class NumberlessRegistrationFlow {
244:   private state: RegistrationFlowState = new RegistrationFlowState();
245:   private billing: BillingSnapshot;
246:   private service: SignalServiceSnapshot;
247:   private credentialManager: SignalCredentialManager;
248:   private observer: RegistrationFlowObserver;
249:   private sheet: OneTimePurchaseSheet | null = null;
250:   private registrationData: Record<string, Object> = {} as Record<string, Object>;
251:   private settleHandle: number = 0;
252: 
253:   constructor(
254:     billing: BillingSnapshot,
255:     service: SignalServiceSnapshot,
256:     credentialManager: SignalCredentialManager,
257:     observer: RegistrationFlowObserver,
258:     sheet: OneTimePurchaseSheet | null
259:   ) {
260:     this.billing = billing;
261:     this.service = service;
262:     this.credentialManager = credentialManager;
263:     this.observer = observer;
264:     this.sheet = sheet;
265:   }
266: 
267:   /* ----------------------------------------------------------- hydration */
268: 
269:   /**
270:    * Rebuilds the flow from the application owned registration data plus the
271:    * state the external services are known to be in. Nothing here decides
272:    * anything; it only re-establishes what the app already knows.
273:    */
274:   restore(registrationData: Record<string, Object>): void {
275:     this.registrationData = registrationData;
276:     this.state = new RegistrationFlowState();
277:     this.billing.reset();
278:     this.service.reset();
279:     this.hydrate(registrationData);
280:   }
281: 
282:   private hydrate(given: Record<string, Object>): void {
283:     const payment: Record<string, Object> = asRecord(given['payment']);
284:     const flow: Record<string, Object> = asRecord(given['flow']);
285:     const parentLogin: Record<string, Object> = asRecord(given['parentLogin']);
286:     const entered: Record<string, Object> = asRecord(given['enteredLogin']);
287:     const dialogs: Record<string, Object> = asRecord(given['dialogs']);
288: 
289:     this.state.route = asTextOr(asTextOr(given['route'], asTextOr(given['entryRoute'], this.state.route)), this.state.route);
290:     this.state.numberlessRegistrationAvailable = asFlagOr(given['phoneNumberlessRegistrationAvailable'], true);
291:     this.state.numberlessRegistrationEnabled = this.state.numberlessRegistrationAvailable;
292: 
293:     this.state.selectedOption = asTextOr(given['selectedOption'], this.state.selectedOption);
294:     this.state.paymentAvailability = asTextOr(given['paymentAvailability'], asTextOr(given['googlePlayServices'], this.state.paymentAvailability));
295:     this.hydratePrice(asRecord(given['price']), asTextOr(given['price'], ''));
296:     this.state.productId = asTextOr(given['productId'], this.state.productId);
297:     this.state.purchaseOptionId = asTextOr(given['purchaseOptionId'], this.state.purchaseOptionId);
298:     this.state.showSpinner = asFlagOr(given['showSpinner'], asFlag(payment['showSpinner']));
299:     this.state.purchasePreparation = asTextOr(given['purchasePreparation'], this.state.purchasePreparation);
300:     this.state.purchaseSheetPresented = asText(given['purchaseSheet']) === 'open';
301:     this.state.hasUnredeemedPurchase = asFlag(given['hasUnredeemedPurchase']) || asFlag(payment['hasUnredeemedPurchase']) || asFlag(given['ownedUnconsumedPurchase']);
302: 
303:     this.state.dialogs.paymentUnavailable = asFlag(dialogs['paymentUnavailable']);
304:     this.state.dialogs.purchaseFailed = asFlag(dialogs['purchaseFailed']);
305:     this.state.dialogs.saveNotConfirmed = asFlag(dialogs['saveNotConfirmed']);
306:     this.state.dialogs.saveFailed = asFlag(dialogs['saveFailed']);
307:     this.state.dialogs.confirmSkip = asFlag(dialogs['confirmSkip']);
308: 
309:     this.state.flow.aci = asTextOr(flow['aci'], asTextOr(given['aci'], asTextOr(parentLogin['aci'], this.state.flow.aci)));
310:     this.state.flow.accountEntropyPool = asTextOr(flow['accountEntropyPool'], asTextOr(given['accountEntropyPool'], asTextOr(parentLogin['accountEntropyPool'], this.state.flow.accountEntropyPool)));
311:     this.state.flow.e164 = asOptionalIdentity(flow['e164']);
312:     this.state.flow.pni = asOptionalIdentity(flow['pni']);
313:     this.state.flow.storageCapable = asFlagOr(flow['storageCapable'], this.state.flow.storageCapable);
314:     this.state.flow.isPhoneNumberlessAccount = asFlagOr(flow['isPhoneNumberlessAccount'], this.state.flow.isPhoneNumberlessAccount);
315: 
316:     this.state.mode = asTextOr(given['mode'], this.state.mode);
317:     this.state.enteredAccountId = asText(entered['accountId']);
318:     this.state.enteredRecoveryKey = asText(entered['recoveryKey']);
319:     this.state.areCredentialsIncorrect = asFlag(given['areCredentialsIncorrect']);
320:     this.state.isNextEnabled = asFlag(given['isNextEnabled']);
321: 
322:     this.state.isPasswordManagerAvailable = asFlagOr(given['isPasswordManagerAvailable'], this.credentialManager.isAvailable());
323:     this.state.showConfirmSavedSheet = asFlag(given['showConfirmSavedSheet']);
324:     this.state.isReadbackRequested = asText(given['readbackRequest']) === 'held';
325: 
326:     this.state.username = asText(given['username']);
327:     this.state.discriminator = asText(given['discriminator']);
328:     this.state.isDiscriminatorUserSet = asFlag(given['isDiscriminatorUserSet']);
329:     this.state.reservation = asOptionalIdentity(given['reservation']);
330:     this.state.validationError = asOptionalIdentity(given['validationError']);
331:     this.state.isReserving = asFlag(given['isReserving']);
332:     this.state.isSubmittable = asFlag(given['isSubmittable']);
333:     this.state.discriminatorFieldFocused = asFlag(given['discriminatorFieldFocused']);
334: 
335:     this.state.registrationComplete = asFlag(given['registrationComplete']);
336:     this.state.finalRegistrationCommitted = asFlag(given['finalRegistrationCommitted']);
337: 
338:     this.billing.restore(given);
339:     const purchase: Record<string, Object> = asRecord(given['purchase']);
340:     if (isEmptyRecord(purchase) === false) {
341:       this.billing.ownedPurchase = BillingPurchase.fromJson(purchase);
342:     }
343:     if (this.billing.hasOwnedUnredeemedPurchase()) {
344:       this.state.hasUnredeemedPurchase = true;
345:     }
346:     this.service.restore(given);
347:     this.state.paymentAvailability = asTextOr(given['paymentAvailability'], this.state.paymentAvailability);
348: 
349:     const persisted: Record<string, Object> = asRecord(given['persistedSignalLoginPurchase']);
350:     if (isEmptyRecord(persisted) === false) {
351:       this.state.persistedSignalLoginPurchase = SignalLoginPurchaseContext.fromJson(persisted);
352:       this.state.inProgressRegistrationData.signalLoginPurchase = this.state.persistedSignalLoginPurchase;
353:     }
354: 
355:     const receiptContext: string = asText(given['receiptCredentialRequestContext']);
356:     if (receiptContext.length > 0) {
357:       const owned: BillingPurchase | null = this.billing.ownedPurchase;
358:       if (this.state.inProgressRegistrationData.signalLoginPurchase === null && owned !== null && owned.purchaseToken.length > 0) {
359:         const option: BillingProductOption | null = this.billing.product;
360:         this.restorePaidPurchase(new SignalLoginPurchaseContext(owned.purchaseToken, receiptContext));
361:         const restored: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
362:         if (restored !== null && option !== null) {
363:           restored.productId = option.productId;
364:           restored.purchaseOptionId = option.purchaseOptionId;
365:           restored.formattedPrice = option.formattedPrice;
366:         }
367:       }
368:     }
369: 
370:     const readback: Record<string, Object> = asRecord(given['readbackCredential']);
371:     const retrieved: Record<string, Object> = asRecord(given['savedCredentialRetrieved']);
372:     const stored: Record<string, Object> = asRecord(given['passwordManagerStoredCredential']);
373:     if (isEmptyRecord(readback) === false) {
374:       this.credentialManager.seed(UsernamePasswordCredential.fromJson(readback));
375:     } else if (isEmptyRecord(retrieved) === false) {
376:       this.credentialManager.seed(UsernamePasswordCredential.fromJson(retrieved));
377:     } else if (isEmptyRecord(stored) === false) {
378:       this.credentialManager.seed(UsernamePasswordCredential.fromJson(stored));
379:     }
380: 
381:     // Readiness is derived, not remembered: the screens render it from what the
382:     // app currently knows about availability, price and owned purchases.
383:     this.updatePaymentReadiness();
384:   }
385: 
386:   /**
387:    * Recomputes what the payment screen may offer. A purchase cannot be
388:    * submitted until there is either a usable price or a purchase the app has
389:    * already paid for, and the option stays reachable for as long as the store
390:    * might still become usable.
391:    */
392:   private updatePaymentReadiness(): void {
393:     const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
394:     this.state.isPurchaseOptionEnabled = terminal === false;
395:     this.state.isActionEnabled = this.state.isPurchaseOptionEnabled &&
396:       (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
397:     this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
398:   }
399: 
400:   private hydratePrice(price: Record<string, Object>, fallbackType: string): void {
401:     if (isEmptyRecord(price)) {
402:       this.state.price.type = fallbackType.length > 0 ? fallbackType : SignalLoginPrice.Unavailable;
403:       return;
404:     }
405:     this.state.price.type = asTextOr(price['type'], SignalLoginPrice.Unavailable);
406:     this.state.price.formattedPrice = asText(price['formattedPrice']);
407:   }
408: 
409:   /* --------------------------------------------------------- observation */
410: 
411:   private snapshot(): Record<string, Object> {
412:     return JSON.parse(JSON.stringify(this.state)) as Record<string, Object>;
413:   }
414: 
415:   private recordState(): void {
416:     this.observer.recordState(JSON.stringify(this.state));
417:   }
418: 
419:   private effect(name: string, detail: Record<string, Object>): void {
420:     const payload: Record<string, Object> = detail;
421:     payload['name'] = name;
422:     this.observer.recordEffect(JSON.stringify(payload));
423:   }
