425:   /* ------------------------------------------------------ entry selection */
426: 
427:   /** Chooses the ordinary phone number path. It is always offered. */
428:   startPhoneNumberRegistration(): void {
429:     this.state.phoneNumberRegistrationEnabled = true;
430:     this.pushRoute(RegistrationRoute.PhoneNumberEntry);
431:   }
432: 
433:   /**
434:    * Chooses registration without a phone number. The option is only offered
435:    * when the capability is available; the phone number path is untouched either
436:    * way.
437:    */
438:   startRegistrationWithoutNumber(): void {
439:     if (this.state.numberlessRegistrationAvailable === false) {
440:       return;
441:     }
442:     this.state.numberlessRegistrationEnabled = true;
443:     this.state.route = RegistrationRoute.SignalLoginPayment;
444:     this.state.backStack = [RegistrationRoute.Registration];
445:   }
446: 
447:   /* --------------------------------------------------------- price loading */
448: 
449:   /**
450:    * Loads the anti-spam purchase price.
451:    *
452:    * The product identifier comes from the service configuration and the price
453:    * from the billing client; neither is ever taken from the caller. Loading the
454:    * price never starts or completes a purchase.
455:    */
456:   initializeSignalLoginPayment(): void {
457:     if (this.state.numberlessRegistrationAvailable === false) {
458:       return;
459:     }
460:     this.state.route = RegistrationRoute.SignalLoginPayment;
461:     this.state.selectedOption = SignalLoginPaymentOption.Purchase;
462:     this.state.numberlessRegistrationEnabled = true;
463:     this.state.purchaseResult = '';
464:     this.state.purchaseError = '';
465:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
466:     this.state.purchaseSheetPresented = false;
467:     this.state.isPriceLoading = true;
468:     this.state.showSpinner = true;
469:     this.recordState();
470: 
471:     this.effect('getLoginConfiguration', {} as Record<string, Object>);
472:     const productId: string = this.service.loginConfiguration.playProductId;
473:     this.effect('queryBillingProduct', { 'productId': productId } as Record<string, Object>);
474: 
475:     this.state.paymentAvailability = this.billing.availability();
476:     this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
477:     this.applyPrice(productId, this.billing.product);
478:     this.updatePaymentReadiness();
479: 
480:     this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
481:     this.state.isPriceLoading = false;
482:     this.state.showSpinner = false;
483:     this.recordState();
484:   }
485: 
486:   /**
487:    * Re-runs the price lookup. Used both after a transient failure and after the
488:    * user repaired a missing billing service.
489:    */
490:   reloadSignalLoginPaymentPrice(): void {
491:     if (this.state.numberlessRegistrationAvailable === false) {
492:       return;
493:     }
494:     this.state.isPriceLoading = true;
495:     this.state.showSpinner = true;
496:     this.recordState();
497: 
498:     this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
499:     this.state.paymentAvailability = this.billing.availability();
500:     this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
501:     this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);
502:     this.updatePaymentReadiness();
503: 
504:     this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
505:     this.state.isPriceLoading = false;
506:     this.state.showSpinner = false;
507:     this.recordState();
508:   }
509: 
510:   /**
511:    * Applies a billing price.
512:    *
513:    * The price is only shown for the product the service named. A price the
514:    * billing client returned for some other product is not this app's price and
515:    * is never displayed as one.
516:    */
517:   private applyPrice(productId: string, option: BillingProductOption | null): void {
518:     const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
519:     if (option === null || option.formattedPrice.length === 0) {
520:       this.state.price.type = terminal ? SignalLoginPrice.Unavailable : SignalLoginPrice.TransientError;
521:       this.state.price.formattedPrice = '';
522:       return;
523:     }
524:     // When the service has named a product, only a price for that product is
525:     // this app's price; a price for any other product is never shown as one.
526:     if (productId.length > 0 && option.productId !== productId) {
527:       this.state.price.type = terminal ? SignalLoginPrice.Unavailable : SignalLoginPrice.TransientError;
528:       this.state.price.formattedPrice = '';
529:       return;
530:     }
531:     this.state.price.type = SignalLoginPrice.Available;
532:     this.state.price.formattedPrice = option.formattedPrice;
533:     this.state.productId = option.productId;
534:     this.state.purchaseOptionId = option.purchaseOptionId;
535:   }
536: 
537:   /* ------------------------------------------------------------- purchase */
538: 
539:   /**
540:    * Acts on the payment screen's primary button.
541:    *
542:    * With a usable price this crosses to the UI layer, because only the UI layer
543:    * owns an Activity able to present the store purchase sheet. The sheet result
544:    * is held: nothing is redeemed, reported or navigated until the sheet comes
545:    * back. With a purchase the app already paid for, the purchase is resumed and
546:    * no second purchase is ever launched.
547:    */
548:   continuePurchase(): void {
549:     if (this.state.hasUnredeemedPurchase) {
550:       this.resumeOwnedPurchase();
551:       return;
552:     }
553:     if (this.state.isActionEnabled === false) {
554:       return;
555:     }
556:     this.state.purchaseResult = '';
557:     this.state.purchaseError = '';
558:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
559:     this.state.dialogs.purchaseFailed = false;
560:     this.effect('launchPurchaseFlow', {
561:       'launchedBy': 'ui',
562:       'ownsActivity': true,
563:       'productId': this.state.productId,
564:       'purchaseOptionId': this.state.purchaseOptionId,
565:       'formattedPrice': this.state.price.formattedPrice
566:     } as Record<string, Object>);
567: 
568:     const request = new OneTimePurchaseRequest(this.state.productId, this.state.purchaseOptionId, this.state.price.formattedPrice);
569:     if (this.sheet !== null) {
570:       this.sheet.present(request);
571:     }
572:     this.state.purchaseSheetPresented = true;
573:     this.state.showSpinner = true;
574:     this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
575:     this.recordState();
576:   }
577: 
578:   /**
579:    * The store purchase sheet came back without a purchase. Cancellation is a
580:    * settled outcome rather than an error: the spinner is cleared, no receipt is
581:    * requested, no account is touched, and the screen stays ready to retry.
582:    */
583:   completeCancelledPurchase(): void {
584:     this.state.purchaseSheetPresented = false;
585:     this.state.showSpinner = false;
586:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Cancelled;
587:     this.state.purchaseResult = SignalLoginPurchaseResult.Cancelled;
588:     this.state.purchaseError = '';
589:     this.state.dialogs = new SignalLoginPaymentDialogs();
590:     this.updatePaymentReadiness();
591:     this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
592:     this.recordState();
593:   }
594: 
595:   /**
596:    * The purchase sheet came back with a failure. A purchase that was paid for
597:    * stays owned and its persisted context is left untouched, so retrying reuses
598:    * it instead of charging again.
599:    */
600:   completeFailedPurchase(): void {
601:     this.state.purchaseSheetPresented = false;
602:     this.state.showSpinner = false;
603:     this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
604:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
605:     this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
606:     this.state.purchaseError = SignalLoginPurchaseError.AccountCreationFailed;
607:     this.state.dialogs.purchaseFailed = true;
608:     this.updatePaymentReadiness();
609:     this.state.isActionEnabled = true;
610:     this.recordState();
611:   }
612: 
613:   /**
614:    * The payment screen came back to the foreground, typically after the user
615:    * left to repair a billing service the operating system was updating.
616:    * Availability is re-read rather than trusted, and the price is shown loading
617:    * before the recovered price arrives.
618:    */
619:   foregroundPaymentScreen(): void {
620:     this.effect('refreshSignalLoginPaymentAvailability', {
621:       'previousAvailability': this.state.paymentAvailability
622:     } as Record<string, Object>);
623:     this.state.isPriceLoading = true;
624:     this.state.showSpinner = true;
625:     this.recordState();
626: 
627:     const reported: string = asText(this.registrationData['nextAvailability']);
628:     if (reported.length > 0) {
629:       this.billing.googlePlayServices = reported;
630:       this.billing.billingAvailable = true;
631:     }
632:     this.state.paymentAvailability = this.billing.availability();
633:     this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
634:     const requeried: string = asText(this.registrationData['nextPrice']);
635:     if (requeried.length > 0) {
636:       const productId: string = this.service.loginConfiguration.playProductId;
637:       const current: BillingProductOption | null = this.billing.product;
638:       this.billing.product = new BillingProductOption(productId, current !== null ? current.purchaseOptionId : '', requeried);
639:     }
640:     this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
641:     this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);
642:     this.updatePaymentReadiness();
643: 
644:     this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
645:     this.state.isPriceLoading = false;
646:     this.state.showSpinner = false;
647:     this.recordState();
648:   }
649: 
650:   /* ------------------------------------------------------------ redemption */
651: 
652:   /**
653:    * The store purchase sheet reported a purchase. The held result is now
654:    * supplied, so the purchase can be redeemed.
655:    */
656:   completePurchase(): void {
657:     this.state.purchaseSheetPresented = false;
658:     this.state.showSpinner = true;
659:     this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
660:     this.recordState();
661:     this.redeemAndRegister();
662:   }
663: 
664:   /**
665:    * The payment screen is reopened, typically after the process was recreated.
666:    * Availability is re-read and the price is reloaded before anything else can
667:    * be attempted.
668:    */
669:   reopenPaymentScreen(): void {
670:     this.state.route = RegistrationRoute.SignalLoginPayment;
671:     this.state.selectedOption = SignalLoginPaymentOption.Purchase;
672:     this.state.showSpinner = false;
673:     this.state.purchaseSheetPresented = false;
674:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
675:   }
676: 
677:   /**
678:    * Resumes a purchase this app already paid for. The purchase is redeemed
679:    * where it stands; a second purchase is never launched and no new charge is
680:    * ever created.
681:    */
682:   resumeOwnedPurchase(): void {
683:     this.effect('resumeOwnedPurchase', { 'launchesPurchase': false, 'recharges': false } as Record<string, Object>);
684:     this.state.purchaseSheetPresented = false;
685:     this.state.purchaseResult = '';
686:     this.state.purchaseError = '';
687:     this.state.showSpinner = true;
688:     this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
689:     this.recordState();
690:     this.redeemAndRegister();
691:   }
692: 
693:   /**
694:    * Exchanges the store purchase for a verified receipt credential and, when
695:    * the account can be created, creates it. Every failure path keeps the paid
696:    * purchase and its request context so the user can retry without paying
697:    * again.
698:    */
699:   private redeemAndRegister(): void {
700:     const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
701:     if (context === null || context.purchaseToken.length === 0) {
702:       this.failRedemption(SignalLoginPurchaseError.PurchaseContextMissing);
703:       return;
704:     }
705:     // The service rejects a different request for the same purchase, so the
706:     // context that was persisted with the purchase is replayed byte for byte.
707:     this.effect('createLoginReceiptCredential', {
708:       'purchaseToken': context.purchaseToken,
709:       'receiptCredentialRequestContext': context.receiptCredentialRequestContext,
710:       'sendsPurchaseTokenAsCredential': false
711:     } as Record<string, Object>);
712: 
713:     const issuance: string = this.service.nextIssuance();
714:     if (issuance !== CreateLoginReceiptCredentialResult.Issued) {
715:       this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialFailure);
716:       return;
717:     }
718:     const credential: ReceiptCredential = new ReceiptCredential(context.receiptCredentialRequestContext, 'receipt-credential-for-' + context.purchaseToken);
719: 
720:     this.effect('verifyReceiptCredential', { 'result': this.service.receiptCredentialVerification } as Record<string, Object>);
721:     if (this.service.receiptCredentialVerification !== ReceiptCredentialVerification.Success) {
722:       this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialInvalid);
723:       return;
724:     }
725: 
726:     this.state.showSpinner = false;
727:     const response: RegistrationResponse | null = this.service.registrationResponse;
728:     if (response === null) {
729:       // The purchase is redeemed and still owned by this app; account creation
730:       // is a separate, retryable step that never charges again.
731:       this.state.purchaseResult = SignalLoginPurchaseResult.Redeemed;
732:       this.state.hasUnredeemedPurchase = true;
733:       this.updatePaymentReadiness();
734:       this.state.isActionEnabled = true;
735:       this.recordState();
736:       return;
737:     }
738:     this.registerFromReceiptCredential(credential, response);
739:   }
740: 
741:   /**
742:    * Creates the account from the verified receipt credential. The store
743:    * purchase identifier is never the registration credential, and the response
744:    * decides whether the account is a numberless one.
745:    */
746:   private registerFromReceiptCredential(credential: ReceiptCredential, response: RegistrationResponse): void {
747:     this.effect('registerAccount', {
748:       'receiptCredential': credential.credential,
749:       'receiptCredentialRequestContext': credential.receiptCredentialRequestContext,
750:       'sendsPurchaseTokenAsCredential': false,
751:       'sendsPhoneNumber': false,
752:       'e164': response.e164,
753:       'pni': response.pni,
754:       'aci': response.aci,
755:       'storageCapable': response.storageCapable
756:     } as Record<string, Object>);
757: 
758:     // Numberless is read from the registration response, never assumed from the
759:     // request, so a response that carried an E.164 can never pass as numberless.
760:     const numberless: boolean = response.isPhoneNumberless();
761:     this.state.flow.aci = response.aci;
762:     this.state.flow.accountEntropyPool = response.accountEntropyPool;
763:     this.state.flow.e164 = response.e164;
764:     this.state.flow.pni = response.pni;
765:     this.state.flow.storageCapable = response.storageCapable;
766:     this.state.flow.isPhoneNumberlessAccount = numberless;
767:     this.state.committedAccount.e164 = response.e164;
768:     this.state.committedAccount.pni = response.pni;
769:     this.state.committedAccount.pniRegistrationId = null;
770: 
771:     // The purchase is consumed exactly once, and only now that the account it
772:     // paid for exists. Its persisted context is dropped in the same step.
773:     const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
774:     if (this.service.consumePurchaseSucceeds && context !== null) {
775:       this.effect('consumePurchase', { 'purchaseToken': context.purchaseToken } as Record<string, Object>);
776:       this.state.hasUnredeemedPurchase = false;
777:       this.clearPurchaseContext();
778:     }
779: 
780:     this.effect('emitRegistrationFlowEvent.Registered', {
781:       'aci': response.aci,
782:       'accountEntropyPool': response.accountEntropyPool,
783:       'isPhoneNumberlessAccount': numberless
784:     } as Record<string, Object>);
785: 
786:     this.state.restoreDecision = RestoreDecision.NewAccount;
787:     this.state.purchaseResult = SignalLoginPurchaseResult.Registered;
788:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Success;
789:     this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
790:     this.state.showSpinner = false;
791:     this.recordState();
792: 
793:     this.openSignalLoginInfo();
794:   }
795: 
796:   private failRedemption(error: string): void {
797:     this.state.showSpinner = false;
798:     this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
799:     this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
800:     this.state.purchaseError = error;
801:     this.state.dialogs.purchaseFailed = true;
802:     // The purchase stays owned and its context stays persisted, so retrying
803:     // reuses it rather than charging again.
804:     this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
805:     this.updatePaymentReadiness();
806:     this.state.isActionEnabled = true;
807:     this.recordState();
808:   }
809: 
810:   /** Drops the paid purchase context once it has been consumed. */
811:   private clearPurchaseContext(): void {
812:     this.state.inProgressRegistrationData.signalLoginPurchase = null;
813:     this.state.persistedSignalLoginPurchase = null;
814:     const owned: BillingPurchase | null = this.billing.ownedPurchase;
815:     if (owned !== null) {
816:       owned.state = BillingPurchaseState.Consumed;
817:       this.billing.ownedPurchase = owned;
818:     }
819:     this.effect('clearPersistedSignalLoginPurchase', {} as Record<string, Object>);
820:   }
