822:   /* --------------------------------------------------------- navigation */
823: 
824:   private pushRoute(route: string): void {
825:     this.state.backStack = [this.state.route];
826:     this.state.route = route;
827:     this.effect('navigate', { 'route': route } as Record<string, Object>);
828:     this.recordState();
829:   }
830: 
831:   /**
832:    * Opens the login information screen.
833:    *
834:    * The pre-registration back stack is cleared here: once the account exists
835:    * there is nothing to go back to, and no phone verification or PIN step is
836:    * inserted anywhere, because a numberless account has neither.
837:    */
838:   private openSignalLoginInfo(): void {
839:     this.state.route = RegistrationRoute.SignalLoginInfo;
840:     this.state.backStack = [];
841:     this.state.showSpinner = false;
842:     this.effect('navigate', {
843:       'route': RegistrationRoute.SignalLoginInfo,
844:       'clearedBackStack': true,
845:       'insertedRoutes': []
846:     } as Record<string, Object>);
847:     this.recordState();
848:   }
849: 
850:   /**
851:    * Advances past credential preservation. Registration does not reach the
852:    * username step until the issued account identifier and recovery key have
853:    * been confirmed.
854:    */
855:   private completeCredentialPreservation(): void {
856:     this.state.savedCredentialConfirmed = true;
857:     this.state.route = RegistrationRoute.AddUsername;
858:     this.state.backStack = [];
859:     this.effect('navigate', {
860:       'route': RegistrationRoute.AddUsername,
861:       'clearedBackStack': true
862:     } as Record<string, Object>);
863:     this.recordState();
864:   }
865: 
866:   /* ---------------------------------------------- password manager pathway */
867: 
868:   /**
869:    * Offers the issued login to the platform password manager. This is the work
870:    * the navigation collector does while leaving the login screen, and the
871:    * outcome is routed straight back to the screen that owns the state.
872:    */
873:   saveCredentialForReadback(): void {
874:     if (this.state.isPasswordManagerAvailable === false) {
875:       this.state.dialogs.saveFailed = true;
876:       this.state.showSpinner = false;
877:       this.state.showConfirmSavedSheet = false;
878:       this.effect('saveCredentialToPasswordManager', { 'available': false } as Record<string, Object>);
879:       this.recordState();
880:       return;
881:     }
882:     const accountId: string = this.state.flow.aci;
883:     const recoveryKey: string = this.state.flow.accountEntropyPool;
884:     this.effect('saveCredentialToPasswordManager', {
885:       'username': normalizeAccountId(accountId),
886:       'password': recoveryKey,
887:       'routedTo': 'SignalLoginInfoViewModel'
888:     } as Record<string, Object>);
889:     this.credentialManager.saveCredential(accountId, recoveryKey);
890:     this.state.showSpinner = true;
891:     this.state.isReadbackRequested = true;
892:     this.state.showConfirmSavedSheet = true;
893:     this.state.savedCredentialConfirmed = false;
894:     this.state.dialogs.saveFailed = false;
895:     this.state.dialogs.saveNotConfirmed = false;
896:     this.recordState();
897:   }
898: 
899:   /**
900:    * The read-back of the saved credential came back. A save is not trusted on
901:    * its own: the credential is filtered by this account, its username is
902:    * normalized to an account identifier and its password parsed as a recovery
903:    * key, and only an exact two part match counts as safely stored.
904:    */
905:   completePasswordManagerReadback(): void {
906:     const accountId: string = this.state.flow.aci;
907:     this.state.showSpinner = true;
908:     this.effect('getCredentialFromPasswordManager', {
909:       'accountId': normalizeAccountId(accountId)
910:     } as Record<string, Object>);
911: 
912:     const readBack: UsernamePasswordCredential | null = this.credentialManager.getCredential(accountId);
913:     if (readBack === null) {
914:       this.failReadback();
915:       return;
916:     }
917:     const matched: boolean = credentialMatches(accountId, this.state.flow.accountEntropyPool, readBack.username, readBack.password);
918:     this.effect('compareReadBackCredential', {
919:       'type': readBack.type,
920:       'accountIdMatches': normalizeAccountId(readBack.username) === normalizeAccountId(accountId),
921:       'recoveryKeyMatches': matched,
922:       'confirmed': matched
923:     } as Record<string, Object>);
924:     if (matched === false) {
925:       this.failReadback();
926:       return;
927:     }
928:     this.state.dialogs.saveNotConfirmed = false;
929:     this.state.dialogs.saveFailed = false;
930:     this.state.showConfirmSavedSheet = false;
931:     this.state.showSpinner = false;
932:     this.recordState();
933:     this.completeCredentialPreservation();
934:   }
935: 
936:   /**
937:    * The saved credential could not be confirmed. The user stays on the login
938:    * screen and can either save again or record the credential by hand.
939:    */
940:   private failReadback(): void {
941:     this.state.showSpinner = false;
942:     this.state.showConfirmSavedSheet = false;
943:     this.state.savedCredentialConfirmed = false;
944:     this.state.dialogs.saveNotConfirmed = true;
945:     this.state.route = RegistrationRoute.SignalLoginInfo;
946:     this.recordState();
947:   }
948: 
949:   /* ------------------------------------------------------- manual recording */
950: 
951:   /** Opens the manual preservation path. */
952:   startManualCredentialEntry(): void {
953:     this.state.route = RegistrationRoute.SignalLoginManualSaveConfirmation;
954:     this.state.mode = SignalLoginCredentialEntryMode.Enter;
955:     this.state.enteredAccountId = '';
956:     this.state.enteredRecoveryKey = '';
957:     this.state.areCredentialsIncorrect = false;
958:     this.state.accountIdFieldIncorrect = false;
959:     this.state.recoveryKeyFieldIncorrect = false;
960:     this.state.isNextEnabled = false;
961:     this.effect('navigate', { 'route': RegistrationRoute.SignalLoginManualSaveConfirmation } as Record<string, Object>);
962:     this.recordState();
963:   }
964: 
965:   /**
966:    * Records an edit to one of the two credential halves. Editing either half
967:    * clears the incorrect flag, so a mistyped credential stays editable and a
968:    * corrected retry is reachable without recreating the account.
969:    */
970:   updateManualCredentialField(field: string, value: string): void {
971:     if (field === 'accountId') {
972:       this.state.enteredAccountId = value;
973:       this.state.accountIdFieldIncorrect = false;
974:     } else {
975:       this.state.enteredRecoveryKey = value;
976:       this.state.recoveryKeyFieldIncorrect = false;
977:     }
978:     this.state.areCredentialsIncorrect = false;
979:     this.state.isNextEnabled = value.length > 0;
980:     this.recordState();
981:   }
982: 
983:   /**
984:    * Confirms a manually recorded login. Both halves are compared with the
985:    * account material the registration flow already holds; a mismatch flags both
986:    * fields, because either half may have been copied wrongly.
987:    */
988:   submitManualSaveConfirmation(): void {
989:     this.effect('compareEnteredCredential', {
990:       'comparedAgainst': 'RegistrationFlowState',
991:       'comparedAccountId': true,
992:       'comparedRecoveryKey': true
993:     } as Record<string, Object>);
994:     const matched: boolean = credentialMatches(
995:       this.state.flow.aci,
996:       this.state.flow.accountEntropyPool,
997:       this.state.enteredAccountId,
998:       this.state.enteredRecoveryKey
999:     );
1000:     if (matched === false) {
1001:       this.state.areCredentialsIncorrect = true;
1002:       this.state.accountIdFieldIncorrect = true;
1003:       this.state.recoveryKeyFieldIncorrect = true;
1004:       this.state.isNextEnabled = true;
1005:       this.state.savedCredentialConfirmed = false;
1006:       this.effect('manualSaveConfirmationRejected', {
1007:         'staysOnRoute': RegistrationRoute.SignalLoginManualSaveConfirmation
1008:       } as Record<string, Object>);
1009:       this.recordState();
1010:       return;
1011:     }
1012:     this.state.areCredentialsIncorrect = false;
1013:     this.state.accountIdFieldIncorrect = false;
1014:     this.state.recoveryKeyFieldIncorrect = false;
1015:     this.state.isNextEnabled = true;
1016:     this.state.savedCredentialConfirmed = true;
1017:     this.state.mode = SignalLoginCredentialEntryMode.ConfirmSaved;
1018:     this.effect('emitRegistrationFlowEvent.AccountCredentialRecorded', {} as Record<string, Object>);
1019:     this.recordState();
1020:     this.completeCredentialPreservation();
1021:   }
1022: 
1023:   /* --------------------------------------------------------------- username */
1024: 
1025:   /** The username draft changed. */
1026:   changeUsername(value: string): void {
1027:     this.cancelReservationSettle();
1028:     this.state.username = value;
1029:     this.state.reservation = null;
1030:     this.state.validationError = null;
1031:     this.state.isSubmittable = false;
1032:     if (value.length === 0) {
1033:       this.state.isReserving = false;
1034:       this.recordState();
1035:       return;
1036:     }
1037:     if (this.state.discriminator.length > 0 && this.state.discriminatorFieldFocused === false) {
1038:       this.requestUserChosenReservation();
1039:       return;
1040:     }
1041:     this.recordState();
1042:   }
1043: 
1044:   /** The discriminator field gained focus. */
1045:   focusDiscriminator(): void {
1046:     this.cancelReservationSettle();
1047:     this.state.discriminatorFieldFocused = true;
1048:     this.state.isReserving = false;
1049:     this.recordState();
1050:   }
1051: 
1052:   /**
1053:    * The discriminator changed. Typing a discriminator reserves the exact
1054:    * pairing the user asked for once they stop; clearing it drops that pairing,
1055:    * because a reservation for digits the screen no longer holds can never be
1056:    * confirmed.
1057:    */
1058:   changeDiscriminator(value: string): void {
1059:     if (value.length === 0) {
1060:       this.clearUserChosenDiscriminator();
1061:       return;
1062:     }
1063:     this.cancelReservationSettle();
1064:     this.state.discriminator = value;
1065:     this.state.isDiscriminatorUserSet = true;
1066:     this.state.validationError = null;
1067:     this.state.isSubmittable = false;
1068:     this.state.isReserving = true;
1069:     this.recordState();
1070:     this.scheduleReservationSettle();
1071:   }
1072: 
1073:   /**
1074:    * Clears a user chosen discriminator. The exact reservation made for the
1075:    * erased pairing is invalidated immediately and cannot be confirmed, and no
1076:    * fresh reservation is asked for until the field loses focus.
1077:    */
1078:   clearUserChosenDiscriminator(): void {
1079:     this.cancelReservationSettle();
1080:     this.state.discriminator = '';
1081:     this.state.isDiscriminatorUserSet = false;
1082:     this.state.reservation = null;
1083:     this.state.validationError = null;
1084:     this.state.isReserving = false;
1085:     this.state.isSubmittable = false;
1086:     this.recordState();
1087:   }
1088: 
1089:   /** The discriminator field lost focus, so reservations may start again. */
1090:   loseDiscriminatorFocus(): void {
1091:     this.state.discriminatorFieldFocused = false;
1092:     this.cancelReservationSettle();
1093:     if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0 && this.state.reservation !== null) {
1094:       this.state.isSubmittable = this.state.username.length > 0;
1095:       this.recordState();
1096:       return;
1097:     }
1098:     this.requestServiceAssignedReservation();
1099:   }
1100: 
1101:   private scheduleReservationSettle(): void {
1102:     this.settleHandle = setTimeout(() => {
1103:       this.settleHandle = 0;
1104:       this.settleReservation();
1105:     }, RESERVATION_SETTLE_MILLISECONDS);
1106:   }
1107: 
1108:   private cancelReservationSettle(): void {
1109:     if (this.settleHandle !== 0) {
1110:       clearTimeout(this.settleHandle);
1111:       this.settleHandle = 0;
1112:     }
1113:   }
1114: 
1115:   /**
1116:    * Runs after the user stopped typing. A reservation is never requested while
1117:    * the field still has focus, because the response would race an edit that has
1118:    * not reached the flow yet.
1119:    */
1120:   private settleReservation(): void {
1121:     if (this.state.discriminatorFieldFocused) {
1122:       this.state.isReserving = false;
1123:       return;
1124:     }
1125:     if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0) {
1126:       this.requestUserChosenReservation();
1127:       return;
1128:     }
1129:     this.requestServiceAssignedReservation();
1130:   }
1131: 
1132:   private requestUserChosenReservation(): void {
1133:     const username: string = this.state.username;
1134:     if (username.length === 0) {
1135:       this.state.isReserving = false;
1136:       this.state.isSubmittable = false;
1137:       this.recordState();
1138:       return;
1139:     }
1140:     const reservation: string = username + '.' + this.state.discriminator;
1141:     const validationError: string = this.service.serviceUsernameValidationError;
1142:     this.effect('reserveUsername.' + username + '.userChosen', {
1143:       'reservation': reservation,
1144:       'validationError': validationError
1145:     } as Record<string, Object>);
1146:     this.applyReservation(reservation, validationError);
1147:   }
1148: 
1149:   private requestServiceAssignedReservation(): void {
1150:     const username: string = this.state.username;
1151:     if (username.length === 0) {
1152:       this.state.isReserving = false;
1153:       this.state.isSubmittable = false;
1154:       this.recordState();
1155:       return;
1156:     }
1157:     const assigned: string = this.service.serviceAssignedReservation.length > 0 ? this.service.serviceAssignedReservation : username;
1158:     const validationError: string = this.service.serviceUsernameValidationError;
1159:     this.effect('reserveUsername.' + username + '.serviceAssigned', {
